const imageName=(item:Item,type:string)=>`${item.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'kazari'}.${({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif','image/heic':'heic','image/heif':'heif'} as Record<string,string>)[type]||'jpg'}`;
function ShareDialog({item,includeLink,onClose,notify}:{item:Item;includeLink:boolean;onClose:()=>void;notify:(message:string)=>void}){const [file,setFile]=useState<File|null>(null);const [loading,setLoading]=useState(!!(item.imageUrl||item.pendingImage));const [error,setError]=useState('');const text=[item.title,item.description,item.categories.map(c=>c.name).join(' · '),item.location?.name?`Local: ${item.location.name}`:'',includeLink?`${location.origin}/?space=${item.spaceId}&item=${item.id}`:''].filter(Boolean).join('\n');
 useEffect(()=>{let alive=true;(async()=>{try{let blob:Blob;if(item.pendingImage)blob=item.pendingImage;else if(item.imageUrl){const response=await fetch(item.imageUrl,{credentials:'include'});observeApiBuild(response);if(!response.ok)throw new Error('Não foi possível carregar a imagem.');blob=await response.blob();}else return;if(alive)setFile(new File([blob],imageName(item,blob.type),{type:blob.type||'image/jpeg'}));}catch{if(alive)setError('A imagem original não está disponível. Conecte-se para compartilhar ou salvar.');}finally{if(alive)setLoading(false);}})();return()=>{alive=false;};},[item]);
 const supports=!!(file&&typeof navigator.share==='function'&&navigator.canShare?.({files:[file]}));function send(){if(file&&supports){void navigator.share({files:[file],title:item.title,text}).then(()=>onClose()).catch(e=>{if(e?.name!=='AbortError')notify('Não foi possível compartilhar a imagem.');});return;}if(!file&&typeof navigator.share==='function'){void navigator.share({title:item.title,text}).then(()=>onClose()).catch(e=>{if(e?.name!=='AbortError')notify('Não foi possível compartilhar.');});return;}if(navigator.clipboard){void navigator.clipboard.writeText(text).then(()=>notify('Descrição copiada. Salve a imagem para anexá-la na mensagem.')).catch(()=>notify('Não foi possível copiar a descrição.'));}else window.prompt('Copie a descrição do item:',text);}
 function download(){if(!file)return;const url=URL.createObjectURL(file);const anchor=document.createElement('a');anchor.href=url;anchor.download=file.name;document.body.appendChild(anchor);anchor.click();anchor.remove();window.setTimeout(()=>URL.revokeObjectURL(url),60000);}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="editor-modal" role="dialog" aria-modal="true" aria-label="Compartilhar item"><div className="modal-head"><div><p className="eyebrow">ENVIAR ITEM</p><h2>Compartilhar</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Fechar compartilhamento">×</button></div><p className="small-muted">{loading?'Preparando imagem…':error||(!file?'Este item não tem imagem.':supports?'A imagem e a descrição serão enviadas ao aplicativo escolhido.':'Este navegador não permite compartilhar arquivos diretamente. Salve a imagem e copie a descrição para anexá-la.')}</p>{file&&<button type="button" className="outline full" onClick={download}>Salvar imagem</button>}<div className="modal-actions"><button type="button" className="text-button" onClick={onClose}>Cancelar</button><button type="button" className="primary" disabled={loading||!!error} onClick={send}>{file&&!supports?'Copiar descrição':'Compartilhar'}</button></div></section></div>;
}
const blankMeta:Meta={categories:[],locations:[],fields:[]};
const tempId=()=>`local-${crypto.randomUUID()}`;
