function Login({onLogin}:{onLogin:(u:User)=>void}){
 const [register,setRegister]=useState(false); const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [confirmPassword,setConfirmPassword]=useState(''); const [code,setCode]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();if(register&&password!==confirmPassword){setError('As senhas não coincidem.');return;}setBusy(true);setError('');try{const data=await api<{user:User}>('/api/auth/'+(register?'register':'login'),json('POST',register?{username,password,code:code.trim()}:{username,password}));localStorage.setItem('kazari:last-user',String(data.user.id));await cacheUser(data.user);onLogin(data.user);}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
 return <main className="auth-shell"><div className="auth-mark"><img className="auth-brand-image" src="/brand/header.svg" alt="Kazari"/><p className="eyebrow">CATÁLOGO PESSOAL</p><p className="tagline">A casa, peça por peça.</p></div><form className="auth-card" onSubmit={submit}><h2>{register?'Criar conta':'Bem-vindo de volta'}</h2><label>Usuário<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required minLength={3}/></label><label>Senha<input type="password" autoComplete={register?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} required minLength={register?10:1}/></label>{register&&<label>Confirmar senha<input type="password" autoComplete="new-password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} required minLength={10}/></label>}{register&&<label>Código de convite ou master<input value={code} onChange={e=>setCode(e.target.value)} required autoCapitalize="none" autoCorrect="off" spellCheck={false}/></label>}{error&&<p className="error">{error}</p>}<button className="primary full" disabled={busy}>{busy?'Aguarde…':register?'Criar conta':'Entrar'}</button><button type="button" className="text-button full" onClick={()=>{setRegister(!register);setConfirmPassword('');setError('');}}>{register?'Já tenho uma conta':'Tenho um convite / código master'}</button><p className="auth-note">A primeira conta usa o código master configurado no servidor.</p></form><InstallPrompt/></main>;
}

type InstallPromptEvent=Event&{prompt:()=>Promise<void>;userChoice:Promise<{outcome:'accepted'|'dismissed';platform:string}>};
function InstallPrompt(){const [mobile,setMobile]=useState(false);const [installed,setInstalled]=useState(false);const [expanded,setExpanded]=useState(false);const [dismissed,setDismissed]=useState(false);const [promptEvent,setPromptEvent]=useState<InstallPromptEvent|null>(null);const [ios,setIos]=useState(false);
 useEffect(()=>{const ua=navigator.userAgent;const apple=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);const isMobile=/Android|iPhone|iPad|iPod|Mobile/i.test(ua)||(navigator as Navigator&{userAgentData?:{mobile?:boolean}}).userAgentData?.mobile===true;const media=window.matchMedia('(display-mode: standalone)');const standalone=media.matches||('standalone'in navigator&&(navigator as Navigator&{standalone?:boolean}).standalone===true);setMobile(isMobile);setIos(apple);setInstalled(standalone);const onPrompt=(event:Event)=>{event.preventDefault();setPromptEvent(event as InstallPromptEvent);};const onInstalled=()=>{setInstalled(true);setPromptEvent(null);};media.addEventListener?.('change',onInstalled);window.addEventListener('beforeinstallprompt',onPrompt);window.addEventListener('appinstalled',onInstalled);return()=>{media.removeEventListener?.('change',onInstalled);window.removeEventListener('beforeinstallprompt',onPrompt);window.removeEventListener('appinstalled',onInstalled);};},[]);
 if(!mobile||installed||dismissed)return null;async function activate(){if(promptEvent){await promptEvent.prompt();const choice=await promptEvent.userChoice;if(choice.outcome==='accepted')setInstalled(true);setPromptEvent(null);return;}setExpanded(value=>!value);}
 return <aside className={`install-banner ${expanded?'expanded':''}`} aria-label="Instalar Kazari"><div className="install-copy"><strong>Tenha o Kazari no celular</strong>{expanded&&<p>{ios?'Toque em Compartilhar e depois em “Adicionar à Tela de Início”.':'No menu do navegador, escolha “Instalar app” ou “Adicionar à tela inicial”.'}</p>}</div><button type="button" className="install-action" onClick={activate}>{promptEvent?'Instalar':expanded?'Entendi':'Como instalar'}</button><button type="button" className="install-dismiss" onClick={()=>setDismissed(true)} aria-label="Fechar aviso de instalação">×</button></aside>;
}

function App(){
 const [user,setUser]=useState<User|null>(null); const [spaces,setSpaces]=useState<Space[]>([]); const [spaceId,setSpaceId]=useState<number|null>(null);const [spacesReady,setSpacesReady]=useState(false);const [spacesLoadError,setSpacesLoadError]=useState('');const [spacesRetry,setSpacesRetry]=useState(0);
 const [items,setItems]=useState<Item[]>([]); const [nextCursor,setNextCursor]=useState<string|null>(null);const [catalogLoading,setCatalogLoading]=useState(false); const [trash,setTrash]=useState<Item[]>([]); const [meta,setMeta]=useState<Meta>(blankMeta);
 const [tab,setTab]=useState<Tab>('catalog'); const [query,setQuery]=useState(''); const [filterCat,setFilterCat]=useState(''); const [filterLoc,setFilterLoc]=useState('');
 const [inventoryFilter,setInventoryFilter]=useState(''); const [sort,setSort]=useState('updated_desc'); const catalogRequest=useRef(0);
 const [sharing,setSharing]=useState<Item|null>(null); const [queuedConflict,setQueuedConflict]=useState<{operationId:string;payload:Record<string,unknown>;remote:Item}|null>(null);const syncing=useRef(false);
 const [filtersOpen,setFiltersOpen]=useState(false);const [catalogView,setCatalogView]=useState<'cards'|'list'>(()=>{try{return localStorage.getItem('kazari:catalog-view')==='list'?'list':'cards';}catch{return 'cards';}});
 const [offline,setOffline]=useState(!navigator.onLine); const [pending,setPending]=useState(0); const [lastSync,setLastSync]=useState(''); const [busy,setBusy]=useState(false); const [notice,setNotice]=useState(''); const [editing,setEditing]=useState<Item|null|false>(false); const [viewing,setViewing]=useState<Item|null>(null); const [includeChildren,setIncludeChildren]=useState(false);
 const [newSpace,setNewSpace]=useState(''); const [inviteCode,setInviteCode]=useState(''); const [shareLink,setShareLink]=useState(false); const [members,setMembers]=useState<SpaceMember[]>([]); const [memberUsername,setMemberUsername]=useState(''); const [memberRole,setMemberRole]=useState<'editor'|'reader'>('editor'); const [deletedSpaces,setDeletedSpaces]=useState<DeletedSpace[]>([]); const [deleteSpaceName,setDeleteSpaceName]=useState(''); const [deleteSpaceAcknowledged,setDeleteSpaceAcknowledged]=useState(false);const [adminUsers,setAdminUsers]=useState<AdminUserRecord[]>([]);const [adminUsersLoading,setAdminUsersLoading]=useState(false);const [adminUsersError,setAdminUsersError]=useState('');const [adminUsersRetry,setAdminUsersRetry]=useState(0);const [conflict,setConflict]=useState<{local:Item;remote:Item;payload:any;file:File|null;mode:string}|null>(null);const [updateReady,setUpdateReady]=useState(false); const syncRef=useRef<()=>Promise<void>>(async()=>{});const catalogItemsRef=useRef<Item[]>([]);
 const noteTimer=useRef<number|undefined>(undefined); const currentSpace=spaces.find(s=>s.id===spaceId);
 useEffect(()=>{catalogItemsRef.current=items;},[items]);
 const notify=(message:string)=>{setNotice(message);window.clearTimeout(noteTimer.current);noteTimer.current=window.setTimeout(()=>setNotice(''),3500);};
 const cacheCurrent=useCallback(async(uid=user?.id,sid=spaceId,list=items)=>{if(uid&&sid)await cacheItems(uid,sid,list);},[user?.id,spaceId,items]);
 const closeModal=(afterClose:()=>void)=>{const backdrops=Array.from(document.querySelectorAll<HTMLElement>('.modal-backdrop'));const active=backdrops.at(-1);if(!active||active.classList.contains('is-closing'))return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){afterClose();return;}active.classList.add('is-closing');window.setTimeout(afterClose,360);};

 useEffect(()=>{
  if(editing===false&&!viewing&&!filtersOpen&&!sharing)return;
  const body=document.body;const y=window.scrollY;
  const previous={position:body.style.position,top:body.style.top,left:body.style.left,width:body.style.width,overflow:body.style.overflow};
  body.style.position='fixed';body.style.top=`-${y}px`;body.style.left='0';body.style.width='100%';body.style.overflow='hidden';
  return()=>{body.style.position=previous.position;body.style.top=previous.top;body.style.left=previous.left;body.style.width=previous.width;body.style.overflow=previous.overflow;window.scrollTo(0,y);};
 },[editing,viewing,filtersOpen,sharing]);

 useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(event.key!=='Escape')return;if(sharing){setSharing(null);return;}if(conflict){setConflict(null);return;}if(filtersOpen)return closeModal(()=>setFiltersOpen(false));if(editing!==false)return closeModal(()=>setEditing(false));if(viewing)return closeModal(()=>setViewing(null));};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[sharing,conflict,filtersOpen,editing,viewing]);
 useEffect(()=>{if(editing===false&&!viewing&&!filtersOpen&&!conflict&&!sharing)return;const previous=document.activeElement instanceof HTMLElement?document.activeElement:null;const onKey=(event:KeyboardEvent)=>{if(event.key!=='Tab'||event.defaultPrevented)return;const dialog=Array.from(document.querySelectorAll<HTMLElement>('.modal-backdrop [role="dialog"]')).at(-1);if(!dialog)return;const nodes=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled):not([type="hidden"]), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex]:not([tabindex="-1"])')).filter(node=>node.getClientRects().length>0);if(!nodes.length)return;const index=nodes.indexOf(document.activeElement as HTMLElement);if(index<0||(event.shiftKey&&index===0)||(!event.shiftKey&&index===nodes.length-1)){event.preventDefault();nodes[event.shiftKey?nodes.length-1:0].focus();}};document.addEventListener('keydown',onKey);return()=>{document.removeEventListener('keydown',onKey);if(previous?.isConnected)previous.focus({preventScroll:true});};},[editing,viewing,filtersOpen,conflict,sharing]);

 useEffect(()=>{try{localStorage.setItem('kazari:catalog-view',catalogView);}catch{}},[catalogView]);

 useEffect(()=>{let active=true;if(tab!=='settings'||!spaceId||currentSpace?.role!=='owner'){setMembers([]);setDeletedSpaces([]);return;}Promise.all([api<SpaceMember[]>(`/api/spaces/${spaceId}/members`),api<DeletedSpace[]>('/api/spaces/deleted')]).then(([rows,deleted])=>{if(active){setMembers(rows);setDeletedSpaces(deleted);}}).catch(e=>{if(active)notify(errorMessage(e));});return()=>{active=false;};},[tab,spaceId,currentSpace?.role]);
 useEffect(()=>{let active=true;if(tab!=='settings'||!user?.isAdmin){setAdminUsers([]);setAdminUsersError('');return;}setAdminUsersLoading(true);setAdminUsersError('');api<AdminUserRecord[]>('/api/admin/users').then(rows=>{if(active)setAdminUsers(rows);}).catch(e=>{if(active)setAdminUsersError(errorMessage(e));}).finally(()=>{if(active)setAdminUsersLoading(false);});return()=>{active=false;};},[tab,user?.isAdmin,adminUsersRetry]);

 useEffect(()=>{let alive=true;(async()=>{try{const result=await api<{user:User}>('/api/auth/me');if(!alive)return;localStorage.setItem('kazari:last-user',String(result.user.id));await cacheUser(result.user);setUser(result.user);}catch(error){if(error instanceof ApiError){localStorage.removeItem('kazari:last-user');return;}const id=Number(localStorage.getItem('kazari:last-user'));const cached=await cachedUser(id);if(alive&&cached){setUser(cached);setOffline(true);}}})();return()=>{alive=false;};},[]);
 useEffect(()=>{if(!user||tab!=='catalog')return;let alive=true;setSpacesReady(false);setSpacesLoadError('');(async()=>{try{const rows=await api<Space[]>('/api/spaces');if(!alive)return;setSpaces(rows);const requested=Number(new URLSearchParams(location.search).get('space'));const chosen=rows.find(s=>s.id===requested)?.id||rows.find(s=>s.id===spaceId)?.id||rows[0]?.id||null;setSpaceId(chosen);setOffline(false);void cacheSpaces(user.id,rows).catch(()=>{});}catch{let rows:Space[]=[];try{rows=await cachedSpaces(user.id) as Space[];}catch{}if(!alive)return;setSpaces(rows);setSpaceId(rows.find(s=>s.id===spaceId)?.id||rows[0]?.id||null);setOffline(true);if(!rows.length)setSpacesLoadError('Não foi possível carregar seus espaços. Verifique a conexão e tente novamente.');}finally{if(alive)setSpacesReady(true);}})();return()=>{alive=false;};},[user?.id,tab,spacesRetry]);

 const loadCatalog=useCallback(async(cursor:string|null=null)=>{
  if(!user||!spaceId)return;const request=++catalogRequest.current;setCatalogLoading(true);
  const filterLocal=(rows:Item[],cm:Meta)=>rows.filter(item=>{
   const term=query.trim().toLocaleLowerCase('pt-BR');
   const text=[item.title,item.description,...Object.values(item.customValues).map(String)].join(' ').toLocaleLowerCase('pt-BR');
   const selected=Number(filterCat);const descendants=selected&&includeChildren?cm.categories.filter(x=>{let p=x.parentId;while(p){if(p===selected)return true;p=cm.categories.find(n=>n.id===p)?.parentId||null;}return false;}).map(x=>x.id):[];
   return (!term||text.includes(term))&&(!filterCat||item.categories.some(c=>c.id===selected||descendants.includes(c.id)))&&(!filterLoc||item.locationId===Number(filterLoc))&&(!inventoryFilter||(inventoryFilter==='favorite'?!!item.inventory?.favorite:(item.inventory?.status||'guardado')===inventoryFilter));
  });
  const fallback=async()=>{const [cached,cm]=await Promise.all([cachedItems(user.id,spaceId),cachedMeta(user.id,spaceId)]);const nextMeta=(cm as Meta)||blankMeta;if(request!==catalogRequest.current)return;const asciiFold=(value:string)=>value.replace(/[A-Z]/g,c=>c.toLowerCase());const compare=(a:string,b:string)=>a<b?-1:a>b?1:0;const direction=sort.endsWith('_asc')?1:-1;const field=sort.startsWith('name_')?'title':sort.startsWith('created_')?'createdAt':'updatedAt';setItems(filterLocal(cached as Item[],nextMeta).sort((a,b)=>direction*(compare(field==='title'?asciiFold(a[field]):a[field],field==='title'?asciiFold(b[field]):b[field])||compare(String(a.id).padStart(20,'0'),String(b.id).padStart(20,'0')))));setNextCursor(null);if(cm)setMeta(nextMeta);setOffline(true);};
  try{
   const params=new URLSearchParams({spaceId:String(spaceId),limit:'48',sort});if(query.trim())params.set('q',query.trim());if(filterCat)params.set('categoryId',filterCat);if(filterLoc)params.set('locationId',filterLoc);if(inventoryFilter==='favorite')params.set('favorite','1');else if(inventoryFilter)params.set('status',inventoryFilter);if(filterCat&&includeChildren)params.set('includeChildren','1');if(cursor)params.set('cursor',cursor);
   const [page,categories,locations,fields]=await Promise.all([
    api<Page>(`/api/items?${params}`),
    api<NodeRecord[]>(`/api/categories?spaceId=${spaceId}`),api<NodeRecord[]>(`/api/locations?spaceId=${spaceId}`),api<CustomField[]>(`/api/fields?spaceId=${spaceId}`),
   ]);if(request!==catalogRequest.current)return;const nextMeta={categories,locations,fields};const next=cursor?[...catalogItemsRef.current,...page.items]:page.items;setItems(next);setNextCursor(page.nextCursor);setMeta(nextMeta);setOffline(false);const stamp=new Date().toISOString();setLastSync(stamp);localStorage.setItem(`kazari:last-sync:${user.id}`,stamp);await Promise.all([(!query&&!filterCat&&!filterLoc&&!inventoryFilter?cacheItems(user.id,spaceId,next):Promise.resolve()),cacheMeta(user.id,spaceId,nextMeta)]);
  }catch{if(!cursor&&request===catalogRequest.current)await fallback();}finally{if(request===catalogRequest.current)setCatalogLoading(false);}
 },[user?.id,spaceId,query,filterCat,filterLoc,includeChildren,inventoryFilter,sort]);
 useEffect(()=>{if(user&&spaceId){const t=window.setTimeout(()=>loadCatalog(),query?180:0);return()=>window.clearTimeout(t);}},[user?.id,spaceId,query,filterCat,filterLoc,loadCatalog]);
 const reloadTrash=useCallback(async()=>{if(!spaceId||!user)return;try{setTrash(await api<Item[]>(`/api/trash?spaceId=${spaceId}`));}catch{setTrash([]);}},[spaceId,user?.id]);
 useEffect(()=>{if(tab==='trash')reloadTrash();},[tab,reloadTrash]);
 const sync=useCallback(async()=>{if(!user||!navigator.onLine||syncing.current)return;syncing.current=true;setOffline(false);try{const r=await syncQueue(user.id);setPending(r.pending);if(r.conflict)setQueuedConflict(r.conflict);if(r.completed){await loadCatalog();if(tab==='trash')await reloadTrash();}if(r.error&&!r.conflict)notify(`Sincronização interrompida: ${r.error}`);else if(r.completed&&!r.conflict)notify(`${r.completed} alteração(ões) sincronizada(s).`);}catch(e){notify(errorMessage(e));}finally{syncing.current=false;}},[user?.id,loadCatalog,tab,reloadTrash]);
 useEffect(()=>{syncRef.current=sync;},[sync]);
 useEffect(()=>{if(!user)return;setLastSync(localStorage.getItem(`kazari:last-sync:${user.id}`)||'');const onOnline=()=>{void syncRef.current();};const onOffline=()=>setOffline(true);const resume=()=>{if(document.visibilityState==='visible'&&navigator.onLine)void syncRef.current();};window.addEventListener('online',onOnline);window.addEventListener('offline',onOffline);document.addEventListener('visibilitychange',resume);void pendingCount(user.id).then(setPending);const timer=window.setInterval(()=>{void pendingCount(user.id).then(count=>{setPending(count);if(count&&navigator.onLine&&document.visibilityState==='visible')void syncRef.current();});},30000);if(navigator.onLine)void syncRef.current();return()=>{window.removeEventListener('online',onOnline);window.removeEventListener('offline',onOffline);document.removeEventListener('visibilitychange',resume);window.clearInterval(timer);};},[user?.id]);
 useEffect(()=>startVersionWatch(),[]);
 useEffect(()=>{const ready=()=>setUpdateReady(true);const cancelled=()=>setUpdateReady(false);window.addEventListener('kazari:update-ready',ready);window.addEventListener('kazari:update-cancelled',cancelled);if(hasPendingVersionUpdate())ready();return()=>{window.removeEventListener('kazari:update-ready',ready);window.removeEventListener('kazari:update-cancelled',cancelled);};},[]);
 useEffect(()=>{if(!updateReady||editing!==false||viewing||filtersOpen||conflict||sharing||pending)return;const timer=window.setTimeout(()=>void applyPendingVersionUpdate(),700);return()=>window.clearTimeout(timer);},[updateReady,editing,viewing,filtersOpen,conflict,sharing,pending]);
 useEffect(()=>{const itemParam=new URLSearchParams(location.search).get('item');if(!itemParam||!spaceId)return;const found=items.find(x=>String(x.id)===itemParam);if(found){setViewing(found);history.replaceState(null,'',location.pathname);return;}let active=true;api<Item>(`/api/items/${itemParam}`).then(item=>{if(active&&item.spaceId===spaceId){setViewing(item);history.replaceState(null,'',location.pathname);}}).catch(()=>{});return()=>{active=false;};},[items,spaceId]);

 async function createSpace(e:FormEvent){e.preventDefault();const name=newSpace.trim();if(!name)return;try{const row=await api<Space>('/api/spaces',json('POST',{name}));const next=[...spaces,row];setSpaces(next);setSpaceId(row.id);await cacheSpaces(user!.id,next);setNewSpace('');notify('Espaço criado.');}catch(e){notify(errorMessage(e));}}
 async function renameSpace(){if(!spaceId||currentSpace?.role!=='owner')return;const name=prompt('Novo nome para o espaço:',currentSpace.name)?.trim();if(!name)return;try{await api(`/api/spaces/${spaceId}`,json('PATCH',{name}));const next=spaces.map(s=>s.id===spaceId?{...s,name}:s);setSpaces(next);await cacheSpaces(user!.id,next);notify('Espaço renomeado.');}catch(e){notify(errorMessage(e));}}
 async function shareSpace(e:FormEvent){e.preventDefault();if(!spaceId)return;try{const member=await api<SpaceMember>(`/api/spaces/${spaceId}/members`,json('POST',{username:memberUsername.trim(),role:memberRole}));setMembers(rows=>[...rows.filter(row=>row.id!==member.id),member].sort((a,b)=>a.username.localeCompare(b.username,'pt-BR')));setMemberUsername('');notify(`${member.username} agora tem acesso ao espaço.`);}catch(e){notify(errorMessage(e));}}
 async function removeSpaceMember(member:SpaceMember){if(!spaceId||member.role==='owner'||!confirm(`Remover o acesso de ${member.username} a este espaço?`))return;try{await api(`/api/spaces/${spaceId}/members/${member.id}`,{method:'DELETE'});setMembers(rows=>rows.filter(row=>row.id!==member.id));notify('Acesso removido.');}catch(e){notify(errorMessage(e));}}
 async function deleteSpace(){if(!currentSpace||currentSpace.role!=='owner'||deleteSpaceName!==currentSpace.name||!deleteSpaceAcknowledged)return;try{const result=await api<{deletedAt:string;restoreDays:number}>(`/api/spaces/${currentSpace.id}`,json('DELETE',{confirmName:deleteSpaceName}));const next=spaces.filter(space=>space.id!==currentSpace.id);setSpaces(next);setSpaceId(next.find(space=>space.role==='owner')?.id||next[0]?.id||null);await cacheSpaces(user!.id,next);setDeletedSpaces(rows=>[{id:currentSpace.id,name:currentSpace.name,deletedAt:result.deletedAt},...rows]);setDeleteSpaceName('');setDeleteSpaceAcknowledged(false);setTab('catalog');notify('Espaço excluído. Você pode restaurá-lo por 7 dias em Ajustes.');}catch(e){notify(errorMessage(e));}}
 async function restoreSpace(id:number){try{await api(`/api/spaces/${id}/restore`,{method:'POST'});const [active,deleted]=await Promise.all([api<Space[]>('/api/spaces'),api<DeletedSpace[]>('/api/spaces/deleted')]);setSpaces(active);setDeletedSpaces(deleted);setSpaceId(id);await cacheSpaces(user!.id,active);setTab('catalog');notify('Espaço restaurado com todo o conteúdo.');}catch(e){notify(errorMessage(e));}}

 async function signOut(){try{await api('/api/auth/logout',{method:'POST'});}catch{}localStorage.removeItem('kazari:last-user');setUser(null);setSpaces([]);setSpaceId(null);setSpacesReady(false);setSpacesLoadError('');setItems([]);setMeta(blankMeta);}
 async function saveItem(data:any,file:File|null,mode:string){
  if(!user||!spaceId)return;setBusy(true);
  try{
   if(!data.id){
    const localId=tempId();const payload={...data,spaceId,clientId:localId};let item:Item;
    try{item=await api<Item>('/api/items',json('POST',payload));if(file){const form=new FormData();form.append('image',file);form.append('mode',mode);item=await api<Item>(`/api/items/${item.id}/image`,{method:'POST',body:form});}}
    catch(e){if(e instanceof Error&&'status'in e)throw e;const local:Item={...payload,id:localId,description:data.description||'',customValues:data.customValues||{},purchaseUrl:data.purchaseUrl||'',purchaseLabel:data.purchaseLabel||'',locationId:data.locationId||null,imageId:null,imageMode:mode,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),deletedAt:null,categories:meta.categories.filter(x=>data.categoryIds.includes(x.id)).map(x=>({id:x.id,name:x.name,parentId:x.parentId,icon:x.icon})),tags:[],location:meta.locations.find(x=>x.id===data.locationId)||null,imageUrl:null,thumbnailUrl:null,pending:true,pendingImage:file||undefined};await enqueue({userId:user.id,spaceId,kind:'create',localId,payload});if(file)await enqueue({userId:user.id,spaceId,kind:'image',localId,blob:file,filename:file.name,mode});item=local;setPending(await pendingCount(user.id));notify('Item salvo neste aparelho; será enviado quando a rede voltar.');}
    const next=[item,...items];setItems(next);await cacheItems(user.id,spaceId,next);
   }else{
    const id=data.id;const patch={...data,baseUpdatedAt:(editing as Item)?.updatedAt};delete patch.id;let item:Item;
    try{item=await api<Item>(`/api/items/${id}`,json('PATCH',patch));if(file){const form=new FormData();form.append('image',file);form.append('mode',mode);item=await api<Item>(`/api/items/${id}/image`,{method:'POST',body:form});}}
    catch(e){if(e instanceof Error&&'status'in e)throw e;await enqueue({userId:user.id,spaceId,kind:'update',localId:String(id),payload:patch});if(file)await enqueue({userId:user.id,spaceId,kind:'image',localId:String(id),blob:file,filename:file.name,mode});item={...editing as Item,...patch,pending:true,pendingImage:file||undefined,updatedAt:new Date().toISOString()};setPending(await pendingCount(user.id));notify('Alteração salva neste aparelho e aguardando sincronização.');}
    const next=items.map(x=>String(x.id)===String(id)?item:x);setItems(next);await cacheItems(user.id,spaceId,next);
   }
   closeModal(()=>setEditing(false));if(navigator.onLine)loadCatalog();
  }catch(e){if(e instanceof ApiError&&e.status===409&&e.payload?.current&&editing){setConflict({local:editing,remote:e.payload.current as Item,payload:data,file,mode});}else notify(errorMessage(e));}finally{setBusy(false);}
 }
 async function overwriteConflict(){if(!conflict)return;setBusy(true);try{const {id,...patch}=conflict.payload;const item=await api<Item>(`/api/items/${id}`,json('PATCH',{...patch,baseUpdatedAt:conflict.remote.updatedAt,force:true}));if(conflict.file){const form=new FormData();form.append('image',conflict.file);form.append('mode',conflict.mode);await api<Item>(`/api/items/${id}/image`,{method:'POST',body:form});}setItems(rows=>rows.map(row=>String(row.id)===String(item.id)?item:row));setConflict(null);closeModal(()=>setEditing(false));notify('Suas alterações substituíram a versão anterior.');await loadCatalog();}catch(e){notify(errorMessage(e));}finally{setBusy(false);}}
 async function deleteItem(item:Item){if(!confirm('Mover este item para a lixeira? Ele poderá ser restaurado por 7 dias.'))return;try{await api(`/api/items/${item.id}`,{method:'DELETE'});}catch(e){if(e instanceof Error&&'status'in e){notify(errorMessage(e));return;}await enqueue({userId:user!.id,spaceId:item.spaceId,kind:'delete',localId:String(item.id)});setPending(await pendingCount(user!.id));}setItems(items.filter(x=>x.id!==item.id));await cacheCurrent(user!.id,spaceId,items.filter(x=>x.id!==item.id));closeModal(()=>setEditing(false));notify('Item movido para a lixeira por 7 dias.');}
 async function restoreItem(item:Item){try{await api(`/api/items/${item.id}/restore`,{method:'POST'});}catch(e){if(e instanceof Error&&'status'in e){notify(errorMessage(e));return;}await enqueue({userId:user!.id,spaceId:item.spaceId,kind:'restore',localId:String(item.id)});setPending(await pendingCount(user!.id));}setTrash(trash.filter(x=>x.id!==item.id));notify('Item restaurado.');}
 function share(item:Item){setSharing(item);}

 async function queueMeta(path:string,method:string,payload?:unknown){if(!user||!spaceId)return;await enqueue({userId:user.id,spaceId,kind:'meta',path,method,payload});setPending(await pendingCount(user.id));notify('Alteração de organização salva neste aparelho e será enviada quando a rede voltar.');}
 async function addTree(kind:'categories'|'locations',name:string,parentId:number|null,icon:string){if(!name.trim()||!spaceId)return;const payload={spaceId,name:name.trim(),parentId,icon};try{await api(`/api/${kind}`,json('POST',payload));await loadCatalog();}catch(e){if(e instanceof ApiError)notify(errorMessage(e));else await queueMeta(`/api/${kind}`,'POST',payload);}}
 async function updateTree(kind:'categories'|'locations',id:number,data:{name:string;parentId:number|null;icon:string}){try{await api(`/api/${kind}/${id}`,json('PATCH',data));await loadCatalog();notify('Nível atualizado.');}catch(e){if(e instanceof ApiError)notify(errorMessage(e));else await queueMeta(`/api/${kind}/${id}`,'PATCH',data);}}
 async function deleteTree(kind:'categories'|'locations',id:number,name:string){try{await api(`/api/${kind}/${id}`,{method:'DELETE'});}catch(e){if(e instanceof ApiError&&e.status===409){if(!confirm(`Excluir “${name}”? ${e.message} Os subníveis serão movidos para o nível principal.`))return;try{await api(`/api/${kind}/${id}?force=1`,{method:'DELETE'});await loadCatalog();notify('Nível excluído.');}catch(error){notify(errorMessage(error));}}else notify(errorMessage(e));}}
 async function addField(name:string,type:CustomField['type'],options:string[]){if(!name.trim()||!spaceId)return;const payload={spaceId,name,type,options};try{await api('/api/fields',json('POST',payload));await loadCatalog();}catch(e){if(e instanceof ApiError)notify(errorMessage(e));else await queueMeta('/api/fields','POST',payload);}}
 async function updateField(id:number,data:{name:string;type:CustomField['type'];options:string[]}){try{await api(`/api/fields/${id}`,json('PATCH',data));await loadCatalog();notify('Campo atualizado.');}catch(e){if(e instanceof ApiError)notify(errorMessage(e));else await queueMeta(`/api/fields/${id}`,'PATCH',data);}}
 async function deleteField(id:number,name:string){if(!confirm(`Excluir o campo “${name}”? Os valores já preenchidos deixarão de aparecer.`))return;try{await api(`/api/fields/${id}?force=1`,{method:'DELETE'});await loadCatalog();notify('Campo excluído.');}catch(e){if(e instanceof ApiError)notify(errorMessage(e));else await queueMeta(`/api/fields/${id}?force=1`,'DELETE');}}
 async function setAccountStatus(row:AdminUserRecord){const next=!row.disabled;if(!confirm(`${next?'Desativar':'Reativar'} a conta ${row.username}?`))return;try{await api(`/api/admin/users/${row.id}/status`,json('PATCH',{disabled:next}));setAdminUsers(rows=>rows.map(entry=>entry.id===row.id?{...entry,disabled:next}:entry));notify(next?'Conta desativada.':'Conta reativada.');}catch(e){notify(errorMessage(e));}}

 async function makeInvite(){try{const r=await api<{code:string;expiresAt:string}>('/api/invites',json('POST',{}));setInviteCode(r.code);await navigator.clipboard?.writeText(r.code);notify('Convite criado e copiado. Válido por 7 dias.');}catch(e){notify(errorMessage(e));}}


 const categoryOptions=useMemo(()=>meta.categories,[meta.categories]);
 const activeFilterCount=[filterCat,filterLoc].filter(Boolean).length;
 if(!user)return <Login onLogin={setUser}/>;
 if(!spacesReady)return <main className="empty-space"><img className="auth-brand-image" src="/brand/header.svg" alt="Kazari"/><p>Carregando seus espaços…</p></main>;
 if(!spaces.length&&spacesLoadError)return <main className="empty-space"><img className="auth-brand-image" src="/brand/header.svg" alt="Kazari"/><p>{spacesLoadError}</p><button className="primary" onClick={()=>setSpacesRetry(value=>value+1)}>Tentar novamente</button><button className="text-button" onClick={signOut}>Sair</button></main>;
 if(!spaces.length)return <main className="empty-space"><img className="auth-brand-image" src="/brand/header.svg" alt="Kazari"/><p>Comece criando seu primeiro espaço pessoal.</p><form className="inline-form" onSubmit={createSpace}><input placeholder="Ex.: Casa" value={newSpace} onChange={e=>setNewSpace(e.target.value)} required/><button className="primary">Criar espaço</button></form><button className="text-button" onClick={signOut}>Sair</button></main>;

 return <div className="app-shell">
  <header className="topbar"><img className="brand-image" src="/brand/header.svg" alt="Kazari"/><div className="top-actions"><span className={`sync-pill ${offline?'offline':''}`}><i/>{offline?'Offline':pending?`${pending} pendente${pending===1?'':'s'}`:'Sincronizado'}</span><button className="avatar" onClick={()=>setTab('settings')} aria-label="Configurações">{user.avatarUrl?<img src={user.avatarUrl} alt=""/>:(user.displayName||user.username).slice(0,1).toUpperCase()}</button></div></header>
  {tab==='catalog'&&<main className="page"><div className="page-heading"><div className="catalog-heading-copy"><p className="eyebrow">SUA COLEÇÃO</p>{spaces.length>1?<Select className="catalog-space-select" aria-label="Selecionar espaço" value={spaceId||''} onChange={e=>setSpaceId(Number(e.target.value))}>{spaces.map(s=><option key={s.id} value={s.id}>{s.name}{s.role!=='owner'?` · ${s.role==='editor'?'Editor':'Leitor'}`:''}</option>)}</Select>:<h1>{currentSpace?.name||'Catálogo'}</h1>}<p className="muted">Um lugar para cada coisa, com espaço para respirar.</p></div>{currentSpace&&<button className="primary add-button" onClick={()=>setEditing(null)}><span>＋</span><span>Novo item</span></button>}</div>
   <div className="catalog-toolbar"><ImageSearch key={spaceId} spaceId={spaceId} offline={offline} query={query} onQueryChange={setQuery} onOpen={setViewing}/><div className="catalog-control-row"><button type="button" className="filter-trigger" onClick={()=>setFiltersOpen(true)}>Filtros{activeFilterCount>0&&<span className="filter-count">{activeFilterCount}</span>}</button><div className="view-switch" role="group" aria-label="Forma de visualizar"><button type="button" aria-pressed={catalogView==='cards'} onClick={()=>setCatalogView('cards')}>Cards</button><button type="button" aria-pressed={catalogView==='list'} onClick={()=>setCatalogView('list')}>Lista</button></div></div></div>
   <div className="catalog-selects"><label className="inventory-filter">Inventário<Select value={inventoryFilter} onChange={e=>setInventoryFilter(e.target.value)}><option value="">Todos os itens</option><option value="favorite">Favoritos</option></Select></label><label className="inventory-filter">Ordenar por<Select value={sort} onChange={e=>setSort(e.target.value)}><option value="updated_desc">Atualização recente</option><option value="updated_asc">Atualização antiga</option><option value="created_desc">Cadastro recente</option><option value="created_asc">Cadastro antigo</option><option value="name_asc">Nome A–Z</option><option value="name_desc">Nome Z–A</option></Select></label></div>
   {offline&&<div className="offline-banner">Você está offline. Exibindo o catálogo sincronizado mais recente neste aparelho.</div>}
   {!items.length?<div className="empty-state"><img className="empty-state-icon" src="/icons/sem-itens.svg" alt="" aria-hidden="true"/><h2>{query?'Nenhum item encontrado':'Sua prateleira está pronta'}</h2><p>{query?'Tente outro termo ou remova os filtros.':'Adicione seu primeiro item para começar o catálogo.'}</p>{!query&&currentSpace?.role!=='reader'&&<button className="outline" onClick={()=>setEditing(null)}>Adicionar primeiro item</button>}</div>:<><div className={`item-grid ${catalogView==='list'?'list-view':''}`}>{items.map(item=><article className="item-card" key={item.id}><ImageThumb item={item} onClick={()=>setViewing(item)}/><div className="item-card-body"><button className="item-title" onClick={()=>setViewing(item)}>{item.title}{item.inventory?.favorite&&<span className="favorite-star" aria-label="Favorito">★</span>}</button>{item.description&&<p className="item-description">{item.description}</p>}<div className="item-meta">{item.categories.slice(0,2).map(c=><span key={c.id}><CategorySymbol name={c.name} icon={c.icon}/>{c.name}</span>)}{item.location&&<span><CategorySymbol name={item.location.name} icon={item.location.icon}/>{item.location.name}</span>}</div>{item.pending&&<span className="pending-label">Aguardando sincronização</span>}<div className="card-actions"><button onClick={()=>share(item)}>Compartilhar</button>{currentSpace?.role!=='reader'&&<button onClick={()=>setEditing(item)}>Editar</button>}</div></div></article>)}</div>{nextCursor&&<div className="load-more"><button className="outline" disabled={catalogLoading} onClick={()=>loadCatalog(nextCursor)}>{catalogLoading?'Carregando…':'Carregar mais itens'}</button></div>}</>}
   {items.length>0&&<footer className="bottom-note"><img src="/brand/footer-symbol.svg" alt=""/><span>A casa, peça por peça.</span></footer>}
  </main>}
  {tab==='trash'&&<main className="page"><div className="page-heading"><div><p className="eyebrow">RECUPERÁVEIS POR 7 DIAS</p><h1>Lixeira</h1><p className="muted">Depois do prazo, os itens e suas imagens são removidos.</p></div></div>{!trash.length?<div className="empty-state"><img className="empty-state-icon" src="/icons/lixeira.svg" alt="" aria-hidden="true"/><h2>A lixeira está vazia</h2></div>:<div className="trash-list">{trash.map(item=><article className="trash-row" key={item.id}><ImageThumb item={item} eager/><div><strong>{item.title}</strong><p>Excluído em {new Date(item.deletedAt!).toLocaleDateString('pt-BR')}</p></div>{currentSpace?.role!=='reader'&&<button className="outline" onClick={()=>restoreItem(item)}>Restaurar</button>}</article>)}</div>}</main>}
  {tab==='organize'&&<main className="page"><div className="page-heading"><div><p className="eyebrow">ESTRUTURE SEU ESPAÇO</p><h1>Organização</h1><p className="muted">Categorias descrevem os itens; locais mostram onde encontrá-los.</p></div></div><div className="organize-grid"><TreeManager title="Categorias" rows={meta.categories} onAdd={(n,p,i)=>addTree('categories',n,p,i)} onUpdate={(id,data)=>updateTree('categories',id,data)} onDelete={(id,name)=>deleteTree('categories',id,name)}/><TreeManager title="Localização física" rows={meta.locations} onAdd={(n,p,i)=>addTree('locations',n,p,i)} onUpdate={(id,data)=>updateTree('locations',id,data)} onDelete={(id,name)=>deleteTree('locations',id,name)}/><FieldManager rows={meta.fields} onAdd={addField} onUpdate={updateField} onDelete={deleteField}/></div></main>}
  {tab==='organize'&&spaceId&&meta.fields.length>1&&<div className="page"><FieldOrder spaceId={spaceId} fields={meta.fields} reload={loadCatalog} notify={notify}/></div>}
  {tab==='settings'&&<main className="page"><div className="page-heading"><div><p className="eyebrow">PREFERÊNCIAS E ACESSO</p><h1>Configurações</h1><p className="muted">Conta {user.username} · espaço {currentSpace?.name}</p></div></div><div className="settings-grid"><section className="manage-card"><SectionTitle title="Espaços" description="Cada espaço organiza um acervo independente."/><form className="inline-form" onSubmit={createSpace}><input placeholder="Nome do novo espaço" value={newSpace} onChange={e=>setNewSpace(e.target.value)} required/><button className="outline">Criar</button></form>{currentSpace?.role==='owner'&&<button className="text-button" onClick={renameSpace}>Renomear espaço atual</button>}{spaces.length>1&&<p className="small-muted">Para trocar o espaço, abra Catálogo e use o seletor no título.</p>}<div className="setting-line"><label>Incluir link interno na mensagem</label><input type="checkbox" checked={shareLink} onChange={e=>setShareLink(e.target.checked)}/></div><p className="small-muted">O link exige acesso a kazari.mockingbird.com.br e login na sua conta. Ele não libera a imagem.</p></section>

   {currentSpace?.role==='owner'&&<section className="manage-card"><SectionTitle title="Compartilhar espaço" description="Convide outra conta do Kazari para consultar ou editar este espaço."/><form className="share-space-form" onSubmit={shareSpace}><label>Nome de usuário<input autoCapitalize="none" autoCorrect="off" spellCheck={false} value={memberUsername} onChange={e=>setMemberUsername(e.target.value)} placeholder="Ex.: ana" required minLength={3}/></label><label>Acesso<Select value={memberRole} onChange={e=>setMemberRole(e.target.value as 'editor'|'reader')}><option value="editor">Pode editar</option><option value="reader">Somente visualizar</option></Select></label><button className="primary">Compartilhar</button></form><p className="small-muted">A outra pessoa precisa ter uma conta criada por convite. Editores podem alterar itens e categorias; leitores só podem consultar.</p><div className="member-list">{members.map(member=><div key={member.id}><span>{member.username}<small>{member.role==='owner'?'Proprietário':member.role==='editor'?'Pode editar':'Somente visualizar'}</small></span>{member.role!=='owner'&&<button className="revoke-member" onClick={()=>removeSpaceMember(member)} aria-label={`Remover acesso de ${member.username}`}>×</button>}</div>)}</div></section>}

   {currentSpace?.role==='owner'&&<section className="manage-card danger-zone"><SectionTitle title="Excluir espaço" description="O espaço e todo o seu conteúdo ficam na lixeira por 7 dias. Durante esse prazo, você pode restaurar tudo em Ajustes."/>{spaces.filter(space=>space.role==='owner').length<=1?<p className="small-muted">Este é seu último espaço ativo. Crie outro espaço antes de excluir este.</p>:<><label className="confirm-space-label">Para confirmar, digite o nome exato: <strong>{currentSpace.name}</strong><input value={deleteSpaceName} onChange={e=>setDeleteSpaceName(e.target.value)} placeholder="Nome do espaço" autoComplete="off"/></label><label className="delete-ack"><input type="checkbox" checked={deleteSpaceAcknowledged} onChange={e=>setDeleteSpaceAcknowledged(e.target.checked)}/><span>Entendo que os membros perderão acesso e que o acervo será excluído permanentemente após 7 dias se eu não o restaurar.</span></label><button type="button" className="danger-button" disabled={deleteSpaceName!==currentSpace.name||!deleteSpaceAcknowledged} onClick={deleteSpace}>Mover espaço para lixeira</button></>}</section>}
   {user.isAdmin&&<section className="manage-card"><SectionTitle title="Convites de conta" description="Código de uso único, válido por 7 dias. A primeira conta usa o código master do servidor."/><button className="primary" onClick={makeInvite}>＋ Gerar convite</button>{inviteCode&&<div className="invite-code"><span>{inviteCode}</span><button onClick={()=>navigator.clipboard?.writeText(inviteCode)}>Copiar</button></div>}</section>}
   {user.isAdmin&&<section className="manage-card"><div className="admin-users-heading"><SectionTitle title="Usuários cadastrados" description="Visão básica das contas e do uso dos espaços, sem dados de autenticação."/><button type="button" className="outline" onClick={()=>setAdminUsersRetry(value=>value+1)} disabled={adminUsersLoading}>{adminUsersLoading?'Atualizando…':'Atualizar'}</button></div>{adminUsersError?<div className="admin-users-error"><p>{adminUsersError}</p><button type="button" className="text-button" onClick={()=>setAdminUsersRetry(value=>value+1)}>Tentar novamente</button></div>:adminUsersLoading&&!adminUsers.length?<p className="small-muted">Carregando usuários…</p>:<><p className="small-muted admin-users-total">{adminUsers.length} {adminUsers.length===1?'conta cadastrada':'contas cadastradas'}</p><div className="admin-users-list">{adminUsers.map(row=><article className={`admin-user-row ${row.disabled?'disabled':''}`} key={row.id}><div className="admin-user-name"><strong>{row.username}</strong>{row.isAdmin&&<span>Admin</span>}{row.disabled&&<span>Desativada</span>}</div><small>Cadastro em {new Date(`${row.createdAt.replace(' ','T')}Z`).toLocaleDateString('pt-BR')} · {row.lastLoginAt?`último acesso em ${new Date(`${row.lastLoginAt.replace(' ','T')}Z`).toLocaleDateString('pt-BR')}`:'sem acesso registrado'}</small><div className="admin-user-stats"><span>{row.ownedSpaces} {row.ownedSpaces===1?'espaço próprio':'espaços próprios'}</span><span>{row.sharedSpaces} compartilhado(s)</span><span>{row.activeItems} {row.activeItems===1?'item ativo':'itens ativos'}</span><span>{(row.storageBytes/1024/1024).toFixed(row.storageBytes<10*1024*1024?1:0)} MB de mídia</span></div>{row.id!==user.id&&<button type="button" className="text-button admin-account-action" onClick={()=>setAccountStatus(row)}>{row.disabled?'Reativar conta':'Desativar conta'}</button>}</article>)}</div></>}</section>}
   {currentSpace?.role==='owner'&&deletedSpaces.length>0&&<section className="manage-card"><SectionTitle title="Espaços na lixeira" description="Espaços excluídos podem ser restaurados por até 7 dias, com itens, categorias e imagens."/><div className="deleted-spaces">{deletedSpaces.map(space=>{const expires=new Date(new Date(space.deletedAt).getTime()+7*86400000);return <div className="deleted-space-row" key={space.id}><span><strong>{space.name}</strong><small>Exclusão permanente em {expires.toLocaleDateString('pt-BR')}</small></span><button className="outline" onClick={()=>restoreSpace(space.id)}>Restaurar</button></div>;})}</div></section>}

   {spaceId&&<section className="manage-card"><SectionTitle title="Exportar inventário" description="Baixe os dados do espaço atual. As fotos permanecem no Kazari."/><div className="photo-actions"><a className="outline export-link" href={`/api/spaces/${spaceId}/export?format=json`} download>Baixar JSON</a><a className="outline export-link" href={`/api/spaces/${spaceId}/export?format=csv`} download>Baixar CSV</a></div></section>}
   <PendingOperations userId={user.id} retry={sync}/>
   {user.isAdmin&&<AdminAudit users={adminUsers} currentUserId={user.id} notify={notify}/>}
   <section className="manage-card"><SectionTitle title="Sincronização e dados locais" description={pending?`${pending} alteração(ões) ainda não enviadas.`:`Tudo sincronizado${lastSync?` em ${new Date(lastSync).toLocaleString('pt-BR')}`:''}.`}/><button className="outline" disabled={offline||!pending} onClick={sync}>Sincronizar agora</button><p className="small-muted">O Kazari guarda até 80 itens recentes e suas miniaturas para consulta offline neste aparelho.</p></section>
   <AccountSettings user={user} onUpdate={updated=>{setUser(updated);void cacheUser(updated);}} onSignOut={signOut}/></div></main>}
  <nav className="bottom-nav" aria-label="Navegação principal"><button className={tab==='catalog'?'active':''} onClick={()=>setTab('catalog')}><img className="nav-icon" src="/icons/catalogo.svg" alt="" aria-hidden="true"/>Catálogo</button><button className={tab==='trash'?'active':''} onClick={()=>setTab('trash')}><img className="nav-icon" src="/icons/lixeira.svg" alt="" aria-hidden="true"/>Lixeira</button>{currentSpace?.role!=='reader'&&<button className={tab==='organize'?'active':''} onClick={()=>setTab('organize')}><img className="nav-icon" src="/icons/categorias.svg" alt="" aria-hidden="true"/>Organizar</button>}<button className={tab==='settings'?'active':''} onClick={()=>setTab('settings')}><img className="nav-icon" src="/icons/ajustes.svg" alt="" aria-hidden="true"/>Ajustes</button></nav>
  {tab==='catalog'&&currentSpace?.role!=='reader'&&<button type="button" className="mobile-fab" onClick={()=>setEditing(null)} aria-label="Adicionar item">＋</button>}
  {filtersOpen&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal(()=>setFiltersOpen(false));}}><section className="editor-modal filter-panel" role="dialog" aria-modal="true" aria-label="Filtros do catálogo"><div className="modal-head"><div><p className="eyebrow">REFINE SUA BUSCA</p><h2>Filtros</h2></div><button type="button" className="icon-button" onClick={()=>closeModal(()=>setFiltersOpen(false))} aria-label="Fechar filtros">×</button></div><div className="filter-fields">{categoryOptions.length>0&&<label className="filter-field">Categoria<Select value={filterCat} onChange={e=>{setFilterCat(e.target.value);if(!e.target.value)setIncludeChildren(false);}}><option value="">Todas as categorias</option>{categoryOptions.map(x=><option key={x.id} value={x.id}>{nodeLabel(x,categoryOptions)}</option>)}</Select></label>}{filterCat&&categoryOptions.some(x=>x.parentId===Number(filterCat))&&<label className="descendant-filter"><input type="checkbox" checked={includeChildren} onChange={e=>setIncludeChildren(e.target.checked)}/>Incluir subcategorias</label>}{meta.locations.length>0&&<label className="filter-field">Localização<Select value={filterLoc} onChange={e=>setFilterLoc(e.target.value)}><option value="">Todos os locais</option>{meta.locations.map(x=><option key={x.id} value={x.id}>{nodeLabel(x,meta.locations)}</option>)}</Select></label>}</div><div className="filter-panel-actions"><button type="button" className="text-button" onClick={()=>{setFilterCat('');setFilterLoc('');setIncludeChildren(false);}}>Limpar filtros</button><button type="button" className="primary" onClick={()=>closeModal(()=>setFiltersOpen(false))}>Ver {items.length} {items.length===1?'item':'itens'}</button></div></section></div>}
  {viewing&&<ItemDetails item={viewing} fields={meta.fields} canEdit={currentSpace?.role!=='reader'} onClose={()=>closeModal(()=>setViewing(null))} onEdit={()=>closeModal(()=>{setViewing(null);setEditing(viewing);})} onShare={()=>share(viewing)}/> }
  {editing!==false&&<ItemEditor item={editing||null} meta={meta} busy={busy} onClose={()=>closeModal(()=>setEditing(false))} onSave={saveItem} onDelete={deleteItem} onShare={share}/>}
  {conflict&&<div className="modal-backdrop"><section className="editor-modal conflict-modal" role="dialog" aria-modal="true" aria-label="Conflito de edição"><div className="modal-head"><div><p className="eyebrow">ALTERAÇÃO CONCORRENTE</p><h2>Escolha qual versão manter</h2></div><button type="button" className="icon-button" aria-label="Fechar conflito" onClick={()=>setConflict(null)}>×</button></div><p className="small-muted">{conflict.remote.updatedAt?`Outra pessoa salvou “${conflict.remote.title}” antes de você.`:'Este item mudou em outro aparelho.'} Você pode revisar a versão atual ou substituir por suas alterações.</p><div className="conflict-summary"><div><small>Versão atual</small><strong>{conflict.remote.title}</strong><p>{conflict.remote.description||'Sem descrição'}</p></div><div><small>Suas alterações</small><strong>{conflict.payload.title}</strong><p>{conflict.payload.description||'Sem descrição'}</p></div></div><div className="modal-actions"><button type="button" className="outline" onClick={()=>{setEditing(conflict.remote);setConflict(null);}}>Revisar versão atual</button><button type="button" className="primary" disabled={busy} onClick={overwriteConflict}>Manter minhas alterações</button></div></section></div>}
  {queuedConflict&&<div className="modal-backdrop"><section className="editor-modal conflict-modal" role="dialog" aria-modal="true" aria-label="Conflito de sincronização"><div className="modal-head"><div><p className="eyebrow">SINCRONIZAÇÃO</p><h2>O item mudou em outro aparelho</h2></div></div><p className="small-muted">Escolha qual versão manter. A fila continuará depois da escolha.</p><div className="conflict-summary"><div><small>Versão no servidor</small><strong>{queuedConflict.remote.title}</strong><p>{queuedConflict.remote.description||'Sem descrição'}</p></div><div><small>Sua alteração neste aparelho</small><strong>{String(queuedConflict.payload.title||'')}</strong><p>{String(queuedConflict.payload.description||'Sem descrição')}</p></div></div><div className="modal-actions"><button type="button" className="outline" onClick={async()=>{if(!user)return;try{await resolveQueuedConflict(user.id,queuedConflict.operationId,'remote');setQueuedConflict(null);await sync();await loadCatalog();}catch(e){notify(errorMessage(e));}}}>Usar versão do servidor</button><button type="button" className="primary" onClick={async()=>{if(!user)return;try{await resolveQueuedConflict(user.id,queuedConflict.operationId,'local',queuedConflict.remote.updatedAt);setQueuedConflict(null);await sync();}catch(e){notify(errorMessage(e));}}}>Manter minha versão</button></div></section></div>}
  {sharing&&<ShareDialog item={sharing} includeLink={shareLink} onClose={()=>setSharing(null)} notify={notify}/>}
  <InstallPrompt/>{notice&&<div className="toast" role="status">{notice}</div>}
 </div>;
}

function SectionTitle({title,description}:{title:string;description:string}){return <div className="section-title"><h2>{title}</h2><p>{description}</p></div>}
function AccountSettings({user,onUpdate,onSignOut}:{user:User;onUpdate:(user:User)=>void;onSignOut:()=>void}){
 const [expanded,setExpanded]=useState(false);const [name,setName]=useState(user.displayName||'');const [current,setCurrent]=useState('');const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [cropFile,setCropFile]=useState<File|null>(null);const fileRef=useRef<HTMLInputElement>(null);
 async function updateProfile(e:FormEvent){e.preventDefault();setBusy(true);setError('');setMessage('');try{const result=await api<{user:User}>('/api/account',json('PATCH',{displayName:name}));onUpdate(result.user);setName(result.user.displayName||'');setMessage('Nome atualizado.');}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
 async function updatePassword(e:FormEvent){e.preventDefault();setError('');setMessage('');if(password!==confirmPassword){setError('As novas senhas não coincidem.');return;}setBusy(true);try{await api('/api/account/password',json('POST',{currentPassword:current,newPassword:password}));setCurrent('');setPassword('');setConfirmPassword('');setMessage('Senha atualizada. As outras sessões foram encerradas.');}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
 async function avatar(file:File|null){if(!file)return;setBusy(true);setError('');setMessage('');try{const form=new FormData();form.append('image',file);const result=await api<{user:User}>('/api/account/avatar',{method:'POST',body:form});onUpdate(result.user);setMessage('Foto atualizada.');}catch(e){setError(errorMessage(e));}finally{setBusy(false);if(fileRef.current)fileRef.current.value='';}}
 async function removeAvatar(){setBusy(true);setError('');setMessage('');try{const result=await api<{user:User}>('/api/account/avatar',{method:'DELETE'});onUpdate(result.user);setMessage('Foto removida.');}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
 return <section className="manage-card account-card"><div className="account-heading"><div className="account-identity"><div className="account-avatar">{user.avatarUrl?<img src={user.avatarUrl} alt=""/>:(user.displayName||user.username).slice(0,1).toUpperCase()}</div><div><h2>Sua conta</h2><p>{user.displayName||user.username}<br/><span>@{user.username}</span></p></div></div><button type="button" className="outline" aria-expanded={expanded} onClick={()=>{setExpanded(!expanded);setError('');setMessage('');}}>{expanded?'Fechar':'Editar perfil'}</button></div>{expanded&&<div className="account-editor"><div className="account-photo-actions"><button type="button" className="outline" disabled={busy} onClick={()=>fileRef.current?.click()}>Escolher foto</button>{user.avatarUrl&&<button type="button" className="text-button" disabled={busy} onClick={removeAvatar}>Remover foto</button>}<input ref={fileRef} className="hidden" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,image/avif" onChange={e=>{const file=e.target.files?.[0];if(file)setCropFile(file);e.currentTarget.value='';}}/></div><p className="small-muted">Você poderá ajustar o enquadramento antes de salvar. A foto será armazenada em até 512 pixels.</p><form onSubmit={updateProfile} className="account-form"><label>Nome de exibição<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} autoComplete="name" placeholder="Como você quer aparecer"/></label><label>Login<input value={user.username} readOnly autoComplete="username"/></label><button className="outline" disabled={busy}>Salvar nome</button></form><form onSubmit={updatePassword} className="account-form account-password"><h3>Alterar senha</h3><label>Senha atual<input type="password" value={current} onChange={e=>setCurrent(e.target.value)} autoComplete="current-password" required maxLength={200}/></label><label>Nova senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password" required minLength={10} maxLength={200}/></label><label>Confirmar nova senha<input type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} autoComplete="new-password" required minLength={10} maxLength={200}/></label><button className="outline" disabled={busy}>Alterar senha</button></form>{error&&<p className="error" role="alert">{error}</p>}{message&&<p className="account-success" role="status">{message}</p>}</div>}<button className="text-button danger-text" onClick={onSignOut}>Sair da conta</button>{cropFile&&<AvatarCropper file={cropFile} onCancel={()=>setCropFile(null)} onConfirm={file=>{setCropFile(null);void avatar(file);}}/>}</section>;
}
function PendingOperations({userId,retry}:{userId:number;retry:()=>Promise<void>}){const [rows,setRows]=useState<Awaited<ReturnType<typeof pendingOperations>>>([]);const [busy,setBusy]=useState(false);useEffect(()=>{let active=true;const refresh=()=>{void pendingOperations(userId).then(data=>{if(active)setRows(data);}).catch(()=>{});};refresh();const timer=window.setInterval(refresh,3000);return()=>{active=false;window.clearInterval(timer);};},[userId]);if(!rows.length)return null;const labels={create:'Novo item',update:'Edição',delete:'Exclusão',restore:'Restauração',image:'Foto',meta:'Organização'};return <section className="manage-card"><SectionTitle title="Envios pendentes" description="Estas alterações continuam guardadas neste aparelho até o servidor confirmar o envio."/><div className="admin-users-list">{rows.map(row=><div className="admin-user-row" key={row.id}><strong>{labels[row.kind]} · {row.name}</strong>{row.error?<p className="error">{row.error}</p>:<small>Aguardando envio</small>}</div>)}</div><button className="outline" type="button" disabled={busy} onClick={async()=>{setBusy(true);try{await retry();setRows(await pendingOperations(userId));}finally{setBusy(false);}}}>{busy?'Enviando…':'Tentar enviar agora'}</button></section>}
function FieldOrder({spaceId,fields,reload,notify}:{spaceId:number;fields:CustomField[];reload:()=>Promise<void>;notify:(message:string)=>void}){const [busy,setBusy]=useState(false);async function move(index:number,delta:number){const ids=fields.map(field=>field.id);const target=index+delta;if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]];setBusy(true);try{await api('/api/fields/order',json('PUT',{spaceId,ids}));await reload();}catch(e){notify(errorMessage(e));}finally{setBusy(false);}}return <section className="manage-card"><SectionTitle title="Ordem dos campos" description="Defina a sequência exibida no cadastro dos itens."/><div className="editable-list">{fields.map((field,index)=><div key={field.id}><span>{field.name}</span><div className="row-actions"><button type="button" disabled={busy||index===0} onClick={()=>move(index,-1)} aria-label={`Subir ${field.name}`}>↑</button><button type="button" disabled={busy||index===fields.length-1} onClick={()=>move(index,1)} aria-label={`Descer ${field.name}`}>↓</button></div></div>)}</div></section>}
function ImageSearch({spaceId,offline,query,onQueryChange,onOpen}:{spaceId:number|null;offline:boolean;query:string;onQueryChange:(value:string)=>void;onOpen:(item:Item)=>void}){const [results,setResults]=useState<Item[]|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const inputRef=useRef<HTMLInputElement>(null);async function search(file:File){if(!spaceId)return;setBusy(true);setError('');try{const form=new FormData();form.append('image',file);setResults(await api<Item[]>(`/api/spaces/${spaceId}/search-image`,{method:'POST',body:form}));}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}return <div className="image-search"><div className="search-box"><span aria-hidden="true">⌕</span><input value={query} onChange={e=>onQueryChange(e.target.value)} placeholder="Buscar itens ou descrições" aria-label="Busca rápida"/>{query&&<button type="button" onClick={()=>onQueryChange('')} aria-label="Limpar busca">×</button>}<button type="button" className="image-search-button" disabled={busy||offline||!spaceId} onClick={()=>inputRef.current?.click()} aria-label={busy?'Buscando por imagem':'Buscar por imagem'} title={offline?'Busca por imagem indisponível offline':'Buscar por imagem'}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8.5" cy="9.5" r="1.5"/><path d="m4 17 5-5 3 3 2-2 6 5"/></svg></button><input ref={inputRef} className="hidden" type="file" accept="image/*" disabled={busy||offline||!spaceId} onChange={e=>{const file=e.target.files?.[0];if(file)void search(file);e.currentTarget.value='';}}/></div>{error&&<p className="error">{error}</p>}{results&&<div><p className="small-muted">Imagens com cores e composição parecidas. {results.length?'':'Nenhuma imagem encontrada.'}</p><div className="image-search-results">{results.map(item=><button type="button" key={item.id} onClick={()=>onOpen(item)}>{item.thumbnailUrl&&<img src={item.thumbnailUrl} alt=""/>}<span>{item.title}</span></button>)}</div><button type="button" className="text-button" onClick={()=>setResults(null)}>Fechar resultados</button></div>}</div>}
function AdminAudit({users,currentUserId,notify}:{users:AdminUserRecord[];currentUserId:number;notify:(message:string)=>void}){const [rows,setRows]=useState<{id:number;action:string;createdAt:string;actor:string;target:string|null}[]>([]);const [selected,setSelected]=useState('');const [error,setError]=useState('');const reload=()=>api<typeof rows>('/api/admin/audit').then(setRows).catch(e=>setError(errorMessage(e)));useEffect(()=>{void reload();},[]);async function revoke(){const target=users.find(row=>String(row.id)===selected);if(!target||!confirm(`Encerrar todas as sessões de ${target.username}?`))return;try{await api(`/api/admin/users/${target.id}/revoke-sessions`,{method:'POST'});notify('Sessões encerradas.');await reload();}catch(e){notify(errorMessage(e));}}return <section className="manage-card"><SectionTitle title="Segurança das contas" description="Encerre sessões e consulte ações administrativas recentes."/><label>Conta<Select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Selecione uma conta</option>{users.filter(row=>row.id!==currentUserId).map(row=><option key={row.id} value={row.id}>{row.username}</option>)}</Select></label><button type="button" className="outline" disabled={!selected} onClick={revoke}>Encerrar sessões</button>{error&&<p className="error">{error}</p>}<div className="admin-users-list">{rows.map(row=><div className="admin-user-row" key={row.id}><strong>{row.action}</strong><small>{row.actor}{row.target?` · ${row.target}`:''} · {new Date(`${row.createdAt.replace(' ','T')}Z`).toLocaleString('pt-BR')}</small></div>)}</div></section>}
function IconPicker({value,onChange,label}:{value:string;onChange:(value:string)=>void;label:string}){return <Select className="icon-picker" value={value} onChange={event=>onChange(event.target.value)} aria-label={label} grid renderOption={(key,text)=><><span className="icon-option-art">{key==='none'?<span className="icon-option-empty" aria-hidden="true">∅</span>:<CategorySymbol name="" icon={key}/>}</span><span className="icon-option-label">{text}</span></>}><option value="none">Sem ícone</option>{iconOptions.map(key=><option key={key} value={key}>{iconLabels[key as keyof typeof iconLabels]}</option>)}</Select>;}
function TreeManager({title,rows,onAdd,onUpdate,onDelete}:{title:string;rows:NodeRecord[];onAdd:(name:string,parentId:number|null,icon:string)=>void;onUpdate:(id:number,data:{name:string;parentId:number|null;icon:string})=>void;onDelete:(id:number,name:string)=>void}){const [name,setName]=useState('');const [parent,setParent]=useState('');const [icon,setIcon]=useState('none');const [editing,setEditing]=useState<number|null>(null);const [draft,setDraft]=useState<{name:string;parentId:string;icon:string}>({name:'',parentId:'',icon:'none'});const infer=(row:NodeRecord)=>row.icon||Object.entries(categoryArt).find(([key])=>row.name.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(key))?.[0]||'none';const begin=(row:NodeRecord)=>{setEditing(row.id);setDraft({name:row.name,parentId:row.parentId?String(row.parentId):'',icon:infer(row)});};return <section className="manage-card"><SectionTitle title={title} description="Níveis ilimitados; escolha um símbolo que seja reconhecível no catálogo."/><form className="tree-add" onSubmit={e=>{e.preventDefault();onAdd(name,Number(parent)||null,icon);setName('');setParent('');setIcon('none');}}><input value={name} onChange={e=>setName(e.target.value)} placeholder="Novo nível" required/><Select value={parent} onChange={e=>setParent(e.target.value)}><option value="">Nível principal</option>{rows.map(r=><option key={r.id} value={r.id}>{nodeLabel(r,rows)}</option>)}</Select><IconPicker label={`Ícone de ${title.toLocaleLowerCase()}`} value={icon} onChange={setIcon}/><button className="outline" aria-label={`Adicionar ${title.toLocaleLowerCase()}`}>＋</button></form><div className="tree-list">{rows.map(row=>editing===row.id?<form key={row.id} className="tree-edit" onSubmit={e=>{e.preventDefault();onUpdate(row.id,{name:draft.name,parentId:draft.parentId?Number(draft.parentId):null,icon:draft.icon});setEditing(null);}}><input value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} required/><Select value={draft.parentId} onChange={e=>setDraft({...draft,parentId:e.target.value})}><option value="">Nível principal</option>{rows.filter(candidate=>candidate.id!==row.id).map(candidate=><option key={candidate.id} value={candidate.id}>{nodeLabel(candidate,rows)}</option>)}</Select><IconPicker label={`Ícone de ${row.name}`} value={draft.icon} onChange={value=>setDraft({...draft,icon:value})}/><button className="primary">Salvar</button><button type="button" className="text-button" onClick={()=>setEditing(null)}>Cancelar</button></form>:<div key={row.id} className={`tree-row ${row.parentId?'child':''}`}><span className="tree-row-name"><CategorySymbol name={row.name} icon={infer(row)}/>{nodeLabel(row,rows)}</span><div className="row-actions"><button type="button" onClick={()=>begin(row)}>Editar</button><button type="button" onClick={()=>onDelete(row.id,row.name)} aria-label={`Remover ${row.name}`}>×</button></div></div>)}</div></section>}
function FieldCreator({onAdd}:{onAdd:(name:string,type:CustomField['type'],options:string[])=>void}){const [name,setName]=useState('');const [type,setType]=useState<CustomField['type']>('text');const [options,setOptions]=useState('');return <form className="field-create" onSubmit={e=>{e.preventDefault();onAdd(name,type,options.split(',').map(x=>x.trim()).filter(Boolean));setName('');setOptions('');}}><input value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: Estado" required/><Select value={type} onChange={e=>setType(e.target.value as CustomField['type'])}><option value="text">Texto</option><option value="number">Número</option><option value="date">Data</option><option value="currency">Valor</option><option value="select">Opção</option><option value="boolean">Sim/não</option></Select>{type==='select'&&<input value={options} onChange={e=>setOptions(e.target.value)} placeholder="Opções separadas por vírgula"/>}<button className="outline">Criar campo</button></form>}
function FieldManager({rows,onAdd,onUpdate,onDelete}:{rows:CustomField[];onAdd:(name:string,type:CustomField['type'],options:string[])=>void;onUpdate:(id:number,data:{name:string;type:CustomField['type'];options:string[]})=>void;onDelete:(id:number,name:string)=>void}){const [editing,setEditing]=useState<number|null>(null);return <section className="manage-card"><SectionTitle title="Campos personalizados" description="Dados próprios para este espaço."/><FieldCreator onAdd={onAdd}/><div className="editable-list field-list">{rows.map(row=>editing===row.id?<FieldEditor key={row.id} field={row} onSave={data=>{onUpdate(row.id,data);setEditing(null);}} onCancel={()=>setEditing(null)}/>:<div key={row.id}><span>{row.name}<small>{row.type}</small></span><div className="row-actions"><button type="button" onClick={()=>setEditing(row.id)}>Editar</button><button type="button" onClick={()=>onDelete(row.id,row.name)} aria-label={`Excluir ${row.name}`}>×</button></div></div>)}</div></section>}
function FieldEditor({field,onSave,onCancel}:{field:CustomField;onSave:(data:{name:string;type:CustomField['type'];options:string[]})=>void;onCancel:()=>void}){const [name,setName]=useState(field.name);const [type,setType]=useState(field.type);const [options,setOptions]=useState(field.options.join(', '));return <form className="field-edit" onSubmit={e=>{e.preventDefault();onSave({name,type,options:options.split(',').map(value=>value.trim()).filter(Boolean)});}}><input value={name} onChange={e=>setName(e.target.value)} required/><Select value={type} onChange={e=>setType(e.target.value as CustomField['type'])}><option value="text">Texto</option><option value="number">Número</option><option value="date">Data</option><option value="currency">Valor</option><option value="select">Opção</option><option value="boolean">Sim/não</option></Select>{type==='select'&&<input value={options} onChange={e=>setOptions(e.target.value)} placeholder="Opções separadas por vírgula"/>}<button className="primary">Salvar</button><button type="button" className="text-button" onClick={onCancel}>Cancelar</button></form>}

function ItemEditor({item,meta,busy,onClose,onSave,onDelete,onShare}:{item:Item|null;meta:Meta;busy:boolean;onClose:()=>void;onSave:(data:any,file:File|null,mode:string)=>void;onDelete:(i:Item)=>void;onShare:(i:Item)=>void}){
 const [title,setTitle]=useState(item?.title||'');const [description,setDescription]=useState(item?.description||'');const [cats,setCats]=useState<number[]>(item?.categories.map(x=>x.id)||[]);const [location,setLocation]=useState(item?.locationId?String(item.locationId):'');const [values,setValues]=useState<Record<string,unknown>>(item?.customValues||{});const [file,setFile]=useState<File|null>(null);const [fileError,setFileError]=useState('');const [mode,setMode]=useState(item?.imageMode||'optimized');const [camera,setCamera]=useState(false);const inputRef=useRef<HTMLInputElement>(null);
 const [favorite,setFavorite]=useState(!!item?.inventory?.favorite);
 function submit(e:FormEvent){e.preventDefault();const payload={...(item?{id:item.id}:{}),title,description,categoryIds:cats,locationId:location?Number(location):null,customValues:values,inventory:{...item?.inventory,favorite}};onSave(payload,file,mode);}
 function toggle(setter:React.Dispatch<React.SetStateAction<number[]>>,current:number[],id:number){setter(current.includes(id)?current.filter(x=>x!==id):[...current,id]);}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="editor-modal" role="dialog" aria-modal="true" aria-label={item?'Editar item':'Novo item'}><div className="modal-head"><div><p className="eyebrow">{item?'DETALHES DO OBJETO':'NOVA PEÇA'}</p><h2>{item?'Editar item':'Adicionar à coleção'}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Fechar editor">×</button></div><form className="item-form" onSubmit={submit}>
  <label>Nome do item<input value={title} onChange={e=>setTitle(e.target.value)} required maxLength={160} placeholder="Ex.: Vaso de cerâmica"/></label><label>Descrição<textarea value={description} onChange={e=>setDescription(e.target.value)} rows={3} placeholder="Detalhes, material, história…"/></label>
 <fieldset><legend>Categorias</legend><div className="choice-list">{meta.categories.map(c=><label key={c.id} className="check-choice"><input type="checkbox" checked={cats.includes(c.id)} onChange={()=>toggle(setCats,cats,c.id)}/><CategorySymbol name={c.name} icon={c.icon}/>{nodeLabel(c,meta.categories)}</label>)}{!meta.categories.length&&<small>Crie categorias em Organizar.</small>}</div></fieldset>
  <label>Localização<Select value={location} onChange={e=>setLocation(e.target.value)}><option value="">Sem localização</option>{meta.locations.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select></label>
  {meta.fields.length>0&&<fieldset><legend>Campos deste espaço</legend>{meta.fields.map(f=><label key={f.id}>{f.name}{f.type==='select'?<Select value={String(values[f.id]??'')} onChange={e=>setValues({...values,[f.id]:e.target.value})}><option value="">Selecione</option>{f.options.map(o=><option key={o}>{o}</option>)}</Select>:f.type==='boolean'?<Select value={String(values[f.id]??'')} onChange={e=>setValues({...values,[f.id]:e.target.value===''?'':e.target.value==='true'})}><option value="">Não informado</option><option value="true">Sim</option><option value="false">Não</option></Select>:<input type={f.type==='currency'||f.type==='number'?'number':f.type==='date'?'date':'text'} step={f.type==='currency'?'0.01':undefined} value={String(values[f.id]??'')} onChange={e=>setValues({...values,[f.id]:e.target.value})}/>}</label>)}</fieldset>}
  <label className="quality-option"><input type="checkbox" checked={favorite} onChange={e=>setFavorite(e.target.checked)}/>Favorito</label>

  <fieldset><legend>Fotografia <span className="optional">1 imagem · até 10 MB após otimização</span></legend>{item?.thumbnailUrl&&!file&&<div className="current-photo"><ImageThumb item={item}/></div>}{file&&<FilePreview file={file}/>}<div className="photo-actions"><button type="button" className="outline" onClick={()=>{setCamera(false);inputRef.current?.click();}}>Escolher da galeria</button><button type="button" className="outline" onClick={()=>{setCamera(true);setTimeout(()=>inputRef.current?.click(),0);}}>Abrir câmera</button><input ref={inputRef} className="hidden" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,image/avif" capture={camera?'environment':undefined} onChange={e=>{const selected=e.target.files?.[0]||null;if(selected&&selected.size>25*1024*1024){setFile(null);setFileError('A imagem de origem precisa ter até 25 MB para ser processada neste aparelho.');}else{setFile(selected);setFileError('');}}}/></div>{fileError&&<p className="error">{fileError}</p>}{file&&<div className="selected-file">{file.name} · {(file.size/1024/1024).toFixed(1)} MB <button type="button" onClick={()=>setFile(null)}>Remover</button></div>}<label className="quality-option"><input type="radio" name="quality" checked={mode==='optimized'} onChange={()=>setMode('optimized')}/>Otimizada — carrega mais rápido e economiza espaço</label><label className="quality-option"><input type="radio" name="quality" checked={mode==='high'} onChange={()=>setMode('high')}/>Qualidade alta — até 3.200 px e 10 MB</label></fieldset>
  {item&&<div className="editor-tools"><button type="button" className="text-button" onClick={()=>onShare(item)}>Compartilhar mensagem</button><button type="button" className="text-button danger-text" onClick={()=>onDelete(item)}>Mover para lixeira</button></div>}<div className="modal-actions"><button type="button" className="text-button" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':item?'Salvar alterações':'Adicionar item'}</button></div>
 </form></section></div>;
}

export default App;
